package com.skycraft.loot;

import com.skycraft.Skycraft;
import net.minecraft.resources.ResourceLocation;
import org.jetbrains.annotations.Nullable;

/**
 * The container taxonomy: loot table ids for every kind of container in the world, for the modules that place them
 * (dungeons, settlements, explorers' sites). Tables are generated by {@code tools/loot_data.py}; see
 * {@code docs/LOOT.md} for each table's contents, gold value and tier curve.
 *
 * <pre>
 *  skycraft:containers/household/{poor,common,wealthy,noble}       bedroom chests, wardrobes (owned: taking is theft)
 *  skycraft:containers/household_stores/{poor,common,wealthy,noble} kitchen barrels, sacks, cupboards (owned)
 *  skycraft:containers/shop/{general,blacksmith,alchemist,inn,temple,farm,mill,mine,barracks,jarl,court_wizard}
 *  skycraft:containers/dungeon/{minor,standard,boss}               urns/barrels, chests, the boss chest
 *  skycraft:containers/dungeon/theme/{nordic,dwemer,falmer,ayleid,velothi,daedric,necromancer,vampire,forsworn}
 *  skycraft:containers/misc/{satchel,knapsack,barrel,urn,sarcophagus,coin_purse}
 *  skycraft:containers/strongbox/{novice,apprentice,adept,expert,master}
 *  skycraft:containers/camp/{bandit,bandit_supplies,giant,hunter,forsworn,smuggler}
 *  skycraft:containers/site/{shrine,daedric_shrine,word_wall,dragon_lair,mine,shipwreck,flotsam,harbor,landing_camp,alchemist_lair}
 *  skycraft:containers/lock_bonus/{novice,apprentice,adept,expert,master}  (rolled once when a lock is picked)
 *  skycraft:containers/corpse/{commoner,bandit,bandit_boss,soldier,mage,mage_boss,draugr,draugr_boss,forsworn,falmer,vampire,dremora,dragon_priest,dragon}
 *  skycraft:containers/reward/{minor,standard,major,legendary}     quest rewards ({@link LootApi#questReward})
 *  skycraft:uniques/&lt;id&gt;                                        one legendary unique ({@link LegendaryUniques})
 * </pre>
 *
 * The old ids ({@code skycraft:chests/dungeon_common}, {@code chests/village/house}...) are aliases of these tables.
 */
public final class Containers {
    private Containers() {}

    public static final String[] WEALTH = {"poor", "common", "wealthy", "noble"};
    public static final String[] LOCKS = {"novice", "apprentice", "adept", "expert", "master"};

    public static ResourceLocation table(String kind, String tier) {
        return new ResourceLocation(Skycraft.MODID, "containers/" + kind + "/" + tier);
    }

    /** A household chest of a wealth tier 0-3 (poor, common, wealthy, noble). */
    public static ResourceLocation household(int wealth) {
        return table("household", WEALTH[Math.max(0, Math.min(3, wealth))]);
    }

    /** A household store (barrel, sack, cupboard) of a wealth tier 0-3. */
    public static ResourceLocation householdStores(int wealth) {
        return table("household_stores", WEALTH[Math.max(0, Math.min(3, wealth))]);
    }

    public static ResourceLocation dungeon(String tier) {
        return table("dungeon", tier);
    }

    public static ResourceLocation unique(String id) {
        return new ResourceLocation(Skycraft.MODID, "uniques/" + id);
    }

    // ------------------------------------------------------------------ rules by table id

    /** Whether a container of this loot table belongs to someone (taking from it is theft). */
    public static boolean isOwned(@Nullable String table) {
        if (table == null) return false;
        return table.contains("chests/village") || table.contains("containers/household") || table.contains("containers/shop/");
    }

    /** Boss chests never restock once looted (Skyrim's cleared dungeons keep their boss chest empty). */
    public static boolean isBoss(@Nullable String table) {
        return table != null && (table.contains("boss") || table.contains("uniques/") || table.contains("dragon_lair")
                || table.contains("word_wall") || table.contains("daedric_shrine") || table.contains("daedric_offerings"));
    }

    /**
     * Days after which a looted container of this table refills (0 = never): households and shops 10 days, dungeon
     * and wilderness containers 30 days (Skyrim's cleared-dungeon respawn), boss chests and placed uniques never.
     */
    public static int restockDays(@Nullable String table) {
        if (table == null || !table.startsWith(Skycraft.MODID + ":") || isBoss(table)) return 0;
        String path = table.substring(Skycraft.MODID.length() + 1);
        if (isOwned(table)) return 10;
        if (path.startsWith("containers/") || path.startsWith("chests/")) return 30;
        return 0;
    }
}
